#!/usr/bin/env python3
from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[1] / "upstream"
client_probe = ROOT / "fabric/src/main/java/org/valkyrienskies/mod/fabric/client/GateEClientProbe.java"
server_probe = ROOT / "fabric/src/main/kotlin/org/valkyrienskies/mod/fabric/common/GateDProbe.kt"

# The client fixture reaches the exact simplified-collider top, but Create then
# leaves it ~1e-4 above the surface with zero motion. A naturally falling player
# normally approaches a floor with negative Y motion. For CI only, give the
# normalized player one vanilla-gravity-sized downward probe so we can distinguish
# a true Create surface-contact failure from a zero-motion touching-edge case.
client = client_probe.read_text(encoding="utf-8")
old_client = '''                                    player.setPos(worldTarget.x, worldTarget.y, worldTarget.z);\n                                    player.setDeltaMovement(Vec3.ZERO);\n                                    LOGGER.info(\n                                        "GATE_E_FIXTURE_COLLIDER_REPOSITIONED collider_index={} local_top={} old_vertical_gap={} target={},{},{}",'''
new_client = '''                                    player.setPos(worldTarget.x, worldTarget.y, worldTarget.z);\n                                    player.setDeltaMovement(new Vec3(0.0, -0.08, 0.0));\n                                    LOGGER.info(\n                                        "GATE_E_FIXTURE_COLLIDER_REPOSITIONED collider_index={} local_top={} old_vertical_gap={} target={},{},{} gravity_probe_y=-0.08",'''
if old_client not in client:
    raise SystemExit("Phase 70 could not find Phase 67/68 client final-surface reposition block")
client = client.replace(old_client, new_client, 1)
client_probe.write_text(client, encoding="utf-8")

# Phase 69 chose the globally nearest collider to the save position. That picked a
# lower surface because it was slightly closer in Z, while the client first chose
# the nearest contraption block top and then its real collision surface. Mirror
# that two-stage reference server-side: choose the simplified collider surface
# closest to the nearest block-top reference, then apply the same one-shot gravity
# probe. This is smoke-fixture normalization only.
server = server_probe.read_text(encoding="utf-8")
old_server = '''                                var best = -1\n                                var bestTop = 0.0\n                                var bestX = 0.0\n                                var bestZ = 0.0\n                                var bestLocalDistanceSq = Double.POSITIVE_INFINITY\n                                for (i in 0 until size) {\n                                    val minX = cx[i] - ex[i] - eps\n                                    val maxX = cx[i] + ex[i] + eps\n                                    val minZ = cz[i] - ez[i] - eps\n                                    val maxZ = cz[i] + ez[i] + eps\n                                    val top = cy[i] + ey[i]\n                                    val targetX = localFeet.x.coerceIn(minX, maxX)\n                                    val targetZ = localFeet.z.coerceIn(minZ, maxZ)\n                                    val dx = targetX - localFeet.x\n                                    val dy = top - localFeet.y\n                                    val dz = targetZ - localFeet.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    if (distanceSq < bestLocalDistanceSq) {\n                                        bestLocalDistanceSq = distanceSq\n                                        bestTop = top\n                                        bestX = targetX\n                                        bestZ = targetZ\n                                        best = i\n                                    }\n                                }\n                                if (best >= 0) {\n                                    val localTarget = net.minecraft.world.phys.Vec3(bestX, bestTop, bestZ)\n                                    val target = toGlobal.invoke(carriage, localTarget, 0.0f) as net.minecraft.world.phys.Vec3\n                                    val dx = target.x - player.x\n                                    val dy = target.y - player.y\n                                    val dz = target.z - player.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    player.setPos(target.x, target.y, target.z)\n                                    player.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO)\n                                    logger.info(\n                                        "GATE_D_FIXTURE_PLAYER_REPOSITIONED old_distance_sq={} local_distance_sq={} target={},{},{} source=nearest_simplified_collider_surface collider_index={} local_top={}",\n                                        distanceSq, bestLocalDistanceSq, target.x, target.y, target.z, best, bestTop)\n                                    return@register\n                                }'''
new_server = '''                                var referenceLocal = localFeet\n                                var referenceWorldDistanceSq = Double.POSITIVE_INFINITY\n                                for (key in blocks.keys) {\n                                    val pos = key as? net.minecraft.core.BlockPos ?: continue\n                                    val localBlockTop = net.minecraft.world.phys.Vec3(pos.x + 0.5, pos.y + 1.0, pos.z + 0.5)\n                                    val worldBlockTop = toGlobal.invoke(carriage, localBlockTop, 0.0f) as? net.minecraft.world.phys.Vec3 ?: continue\n                                    val dx = worldBlockTop.x - player.x\n                                    val dy = worldBlockTop.y - player.y\n                                    val dz = worldBlockTop.z - player.z\n                                    val d2 = dx * dx + dy * dy + dz * dz\n                                    if (d2 < referenceWorldDistanceSq) {\n                                        referenceWorldDistanceSq = d2\n                                        referenceLocal = localBlockTop\n                                    }\n                                }\n\n                                var best = -1\n                                var bestTop = 0.0\n                                var bestX = 0.0\n                                var bestZ = 0.0\n                                var bestReferenceDistanceSq = Double.POSITIVE_INFINITY\n                                for (i in 0 until size) {\n                                    val minX = cx[i] - ex[i] - eps\n                                    val maxX = cx[i] + ex[i] + eps\n                                    val minZ = cz[i] - ez[i] - eps\n                                    val maxZ = cz[i] + ez[i] + eps\n                                    val top = cy[i] + ey[i]\n                                    val targetX = referenceLocal.x.coerceIn(minX, maxX)\n                                    val targetZ = referenceLocal.z.coerceIn(minZ, maxZ)\n                                    val dx = targetX - referenceLocal.x\n                                    val dy = top - referenceLocal.y\n                                    val dz = targetZ - referenceLocal.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    if (distanceSq < bestReferenceDistanceSq) {\n                                        bestReferenceDistanceSq = distanceSq\n                                        bestTop = top\n                                        bestX = targetX\n                                        bestZ = targetZ\n                                        best = i\n                                    }\n                                }\n                                if (best >= 0) {\n                                    val localTarget = net.minecraft.world.phys.Vec3(bestX, bestTop, bestZ)\n                                    val target = toGlobal.invoke(carriage, localTarget, 0.0f) as net.minecraft.world.phys.Vec3\n                                    val dx = target.x - player.x\n                                    val dy = target.y - player.y\n                                    val dz = target.z - player.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    player.setPos(target.x, target.y, target.z)\n                                    player.setDeltaMovement(net.minecraft.world.phys.Vec3(0.0, -0.08, 0.0))\n                                    logger.info(\n                                        "GATE_D_FIXTURE_PLAYER_REPOSITIONED old_distance_sq={} reference_distance_sq={} collider_reference_distance_sq={} target={},{},{} source=block_reference_simplified_surface collider_index={} local_top={} gravity_probe_y=-0.08",\n                                        distanceSq, referenceWorldDistanceSq, bestReferenceDistanceSq, target.x, target.y, target.z, best, bestTop)\n                                    return@register\n                                }'''
if old_server not in server:
    raise SystemExit("Phase 70 could not find Phase 69 server nearest-collider selector")
server = server.replace(old_server, new_server, 1)
server_probe.write_text(server, encoding="utf-8")

print("Phase 70: synchronized the CI ServerPlayer to the same block-referenced simplified collision surface as LocalPlayer and applied a one-shot -0.08 Y gravity probe on both sides to verify Create surface-contact promotion under realistic downward motion; harness-only")

runpy.run_path(str(Path(__file__).with_name("prepare_vs2_26_2_phase71.py")), run_name="__main__")
